import sympy as sp
t=sp.symbols('t')
e=(1-sp.sin(2*t))/(1+sp.sin(2*t))*(sp.cos(t)+sp.sin(t))/(sp.cos(t)-sp.sin(t))
T=sp.tan(t)
opts={'A':(1+2*T)/(1-2*T),'B':(1-T)/(1+T),'C':(1-2*T)/(1+2*T),'D':(1+T)/(1-T)}
pts=[0.3,0.5,1.1]
def eq(a,b): return all(abs(float((a-b).subs(t,p)))<1e-9 for p in pts)
assert eq(e,opts['B'])
for k in 'ACD': assert not eq(e,opts[k])

